import numpy as np

class GSLMedianCalculator:
    def __init__(self):
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define function signature for gsl_stats_median_from_sorted_data
        self.gsl.gsl_stats_median_from_sorted_data.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_int]
        self.gsl.gsl_stats_median_from_sorted_data.restype = ctypes.c_double

    def compute_median(self, sorted_data, stride, n):
        if not isinstance(sorted_data, (list, np.ndarray)):
            raise TypeError("Input data must be a list or numpy array")

        if not all(isinstance(x, (int, float)) for x in sorted_data):
            raise TypeError("All elements must be numeric")

        if n <= 0:
            raise ValueError("Number of elements must be positive")

        if stride <= 0:
            raise ValueError("Stride must be positive")

        # Convert input to numpy array of doubles
        data_array = np.array(sorted_data, dtype=np.float64)

        # Create ctypes pointer to the data array
        data_ptr = data_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

        # Call GSL function
        try:
            median = self.gsl.gsl_stats_median_from_sorted_data(data_ptr, ctypes.c_int(stride), ctypes.c_int(n))
            return float(median)
        except Exception as e:
            raise RuntimeError(f"GSL function failed: {str(e)}") from e

