import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, data, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))(*data)

    def __repr__(self):
        return f"GSLMatrix({self.rows}, {self.cols})"


def copy_matrix(dest, src):
    if dest.rows != src.rows or dest.cols != src.cols:
        return -1

    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.gsl_matrix_memcpy.argtypes = [ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_void_p)]
    gsl.gsl_matrix_memcpy.restype = ctypes.c_int

    dest_ptr = ctypes.pointer(ctypes.c_void_p(dest.data))
    src_ptr = ctypes.pointer(ctypes.c_void_p(src.data))

    result = gsl.gsl_matrix_memcpy(dest_ptr, src_ptr)
    return result


def create_gsl_matrix(np_array):
    rows, cols = np_array.shape
    data = np_array.flatten().tolist()
    return GSLMatrix(data, rows, cols)

