import os

def load_gsl_libraries():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return gsl
    except OSError as e:
        print(f"Error loading GSL libraries: {e}")
        return None

def gsl_cdf_beta_Pinv(gsl, P, a, b):
    if gsl is None:
        return float('nan')

    # Define function signature
    gsl.gsl_cdf_beta_Pinv.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_cdf_beta_Pinv.restype = ctypes.c_int

    result = ctypes.c_double(0.0)
    status = gsl.gsl_cdf_beta_Pinv(P, a, b, ctypes.byref(result))

    if status != 0:
        return float('nan')
    return result.value


def main():
    gsl = load_gsl_libraries()
    if gsl is None:
        print("Failed to load GSL libraries")
        return

    # Test cases
    test_cases = [
        (0.5, 2.0, 2.0),
        (0.95, 5.0, 5.0),
        (0.1, 1.0, 1.0),
        (0.75, 3.0, 1.0)
    ]

    for P, a, b in test_cases:
        try:
            result = gsl_cdf_beta_Pinv(gsl, P, a, b)
            print(f"P={P}, a={a}, b={b} => Inverse CDF: {result}")
        except Exception as e:
            print(f"Error for P={P}, a={a}, b={b}: {e}")

