import ctypes
import sys

class GSLDomainError(Exception):
    pass

try:
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
except OSError as e:
    print(f"Error loading GSL libraries: {e}")
    sys.exit(1)

# Define error handler function
def gsl_error_handler(reason, file, line, gsl_errno):
    raise GSLDomainError(f"GSL error: {reason.decode()} in {file.decode()} at line {line.decode()}")

# Set error handler
ctypes.CFUNCTYPE(None, ctypes.c_char_p, ctypes.c_char_p, ctypes.c_char_p, ctypes.c_int)(gsl_error_handler)

# Define function signature for gsl_sf_legendre_sph_func
ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_sf_legendre_sph_func.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_double]
ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_sf_legendre_sph_func.restype = ctypes.c_double

def compute_legendre_polynomial(l, m, x):
    if not isinstance(l, int) or not isinstance(m, int):
        raise TypeError("l and m must be integers")
    if not isinstance(x, (int, float)):
        raise TypeError("x must be a number")
    if l < 0 or m < 0:
        raise ValueError("l and m must be non-negative")
    if m > l:
        raise ValueError("m cannot be greater than l")
    if abs(x) > 1.0:
        raise ValueError("x must be in the interval [-1, 1]")
    try:
        result = gsl.gsl_sf_legendre_sph_func(l, m, x)
        return float(result)
    except Exception as e:
        raise GSLDomainError(str(e))

# Test cases
try:
    print(compute_legendre_polynomial(2, 0, 0.5))  # Should return 0.75
    print(compute_legendre_polynomial(1, 1, 0.0))   # Should return 0.0
    print(compute_legendre_polynomial(3, 2, -1.0)) # Should return 3.0
except GSLDomainError as e:
    print(f"GSL Domain Error: {e}")
except Exception as e:
    print(f"Error: {e}")

