def numpy_to_gsl_matrix_complex(np_array):
    rows, cols = np_array.shape
    mat = gsl_matrix_complex()
    mat.data = (ctypes.POINTER(gsl_complex) * (rows * cols))()
    for i in range(rows):
        for j in range(cols):
