def compute_weighted_mean(weights, data):
    """Compute the weighted mean using GSL's gsl_stats_wmean function."""

    # Check if inputs are valid lists of floats
    assert isinstance(weights, list) and all(isinstance(x, float) for x in weights), "Weights must be a list of floats"
    assert isinstance(data, list) and all(isinstance(x, float) for x in data), "Data must be a list of floats"

    # Check if input lengths match
    assert len(weights) == len(data), "Weights and data lists must have the same length"

    # Check for empty lists
    assert len(weights) > 0, "Input lists cannot be empty"

    # Load required libraries in the correct order
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        print(f"Error loading GSL libraries: {e}")
        sys.exit(1)

    # Define function signature for gsl_stats_wmean
    gsl.gsl_stats_wmean.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_size_t]
    gsl.gsl_stats_wmean.restype = ctypes.c_double

    # Convert Python lists to C arrays
    weights_array = (ctypes.c_double * len(weights))(*weights)
    data_array = (ctypes.c_double * len(data))(*data)

    # Call the function
    result = gsl.gsl_stats_wmean(data_array, weights_array, ctypes.c_size_t(len(data)))

    return float(result)

