def copy_doubles(X, Y, incX, incY):
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

    gsl.cblas_dcopy.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int]
    gsl.cblas_dcopy.restype = None

    if len(X) < 1 or len(Y) < 1:
        raise ValueError("Input arrays X and Y cannot be empty")

    if incX <= 0 or incY <= 0:
        raise ValueError("Increments incX and incY must be positive")

    try:
        gsl.cblas_dcopy(len(X), (ctypes.c_double * len(X))(*X), incX, (ctypes.c_double * len(Y))(*Y), incY)
    except Exception as e:
        raise RuntimeError(f"Error calling cblas_dcopy: {e}")

    return Y

