import ctypes
import sys

custom_error_handler = ctypes.CFUNCTYPE(None, ctypes.c_char_p, ctypes.c_char_p, ctypes.c_int, ctypes.c_int)

def set_custom_error_handler():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define the custom error handler function
        def error_handler(reason, file, line, gsl_errno):
            print(f"Custom error: {reason.decode()}
File: {file.decode()}
Line: {line.decode()}
Error code: {gsl_errno}")

        # Convert Python function to C compatible function pointer
        c_error_handler = custom_error_handler(error_handler)

        # Call gsl_set_error_handler function
        gsl.gsl_set_error_handler.argtypes = [custom_error_handler]
        gsl.gsl_set_error_handler.restype = ctypes.c_void_p

        prev_handler = gsl.gsl_set_error_handler(c_error_handler)

        return prev_handler
    except Exception as e:
        print(f"Error: {str(e)}")
        return None

if __name__ == "__main__":
    prev_handler = set_custom_error_handler()
    if prev_handler:
        print(f"Previous error handler: {prev_handler}")

