import numpy as np

class GSLMatrix:
    def __init__(self, data, rows, cols):
        self._matrix = ctypes.POINTER(ctypes.c_double)()
        self._rows = rows
        self._cols = cols
        self._data = data
        self._init()

    def _init(self):
        self._matrix = (ctypes.c_double * (self._rows * self._cols))(*self._data)

    def __getitem__(self, key):
        return self._matrix[key]

    @property
    def rows(self):
        return self._rows

    @property
    def cols(self):
        return self._cols


def list_to_gsl_matrix(matrix):
    data = [item for row in matrix for item in row]
    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0
    return GSLMatrix(data, rows, cols)

def add_matrices(matrix_a, matrix_b):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

