    gsl.gsl_matrix_add.restype = ctypes.POINTER(ctypes.c_double)

    mat_a = list_to_gsl_matrix(matrix_a)
    mat_b = list_to_gsl_matrix(matrix_b)

    result = gsl.gsl_matrix_add(mat_a._matrix, mat_b._matrix)
    return [list(result[i*mat_a.cols : (i+1)*mat_a.cols]) for i in range(mat_a.rows)]

