def integrate_function(func, a, b):
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except Exception as e:
        return {"error": str(e)}

    gsl.gsl_integration_qk61.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_integration_qk61.restype = ctypes.c_int

    class gsl_function(ctypes.Structure):
        _fields_ = [("f", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)), 
                   ("params", ctypes.c_void_p)]

    params = ctypes.c_void_p(0)
    f = GSLFunction(func)
    gsl_func = gsl_function(f=f, params=params)

    result = ctypes.c_double(0.0)
    error = ctypes.c_double(0.0)

    status = gsl.gsl_integration_qk61(ctypes.byref(gsl_func), a, b, 0.0, 1e-7, 1e-7, ctypes.byref(result), ctypes.byref(error))

    if status != 0:
