import numpy as np

def compute_weighted_mean(weights, wstride, data, stride):
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        gsl.gsl_stats_wmean.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.POINTER(ctypes.c_double), ctypes.c_size_t]
        gsl.gsl_stats_wmean.restype = ctypes.c_double

        if len(weights) != len(data):
            raise ValueError("Weights and data must be of the same length")

        weights_array = (ctypes.c_double * len(weights))(*weights)
        data_array = (ctypes.c_double * len(data))(*data)

        result = gsl.gsl_stats_wmean(weights_array, wstride, data_array, stride)
        return float(result)
    except Exception as e:
        raise RuntimeError(f"Error computing weighted mean: {str(e)}") from e

