class GSLIntegrationWorkspace(ctypes.Structure):
    _fields_ = []

def integrate_function(f, pts, epsabs, epsrel, limit):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.gsl_integration_qagp.argtypes = [ctypes.POINTER(GSLFunction), ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_double, ctypes.c_double, ctypes.c_int, ctypes.POINTER(GSLIntegrationWorkspace), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_integration_qagp.restype = ctypes.c_int

    func = GSLFunction(f)
    n = len(pts)
    workspace = GSLIntegrationWorkspace()
    result = ctypes.c_double(0.0)
    error = ctypes.c_double(0.0)

    gsl.gsl_integration_qagp(ctypes.byref(func), ctypes.cast(pts.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), ctypes.POINTER(ctypes.c_double)), n, epsabs, epsrel, limit, ctypes.byref(workspace), ctypes.byref(result), ctypes.byref(error))

    return float(result), float(error)

