import sys

class GSLFilterImpulseWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace = ctypes.c_void_p()
        self._init_workspace()

    def _init_workspace(self):
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_filter_impulse_workspace_alloc.restype = ctypes.c_void_p
        gsl.gsl_filter_impulse_workspace_alloc.argtypes = [ctypes.c_int]
        self.workspace = gsl.gsl_filter_impulse_workspace_alloc(self.size)

    def apply_filter(self, signal, threshold):
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_filter_impulse.restype = ctypes.c_int
        gsl.gsl_filter_impulse.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_double]
        filtered = (ctypes.c_double * len(signal))()
        outliers = (ctypes.c_int * len(signal))()
        result = gsl.gsl_filter_impulse(self.workspace, ctypes.cast(filtered, ctypes.POINTER(ctypes.c_double)), ctypes.cast(signal, ctypes.POINTER(ctypes.c_double)), len(signal), threshold)
        assert result == 0, "Filtering failed"
        return np.array(filtered), np.array(outliers)

