        print("Usage: python script.py N K t")
        sys.exit(1)

    N = int(sys.argv[1])
    K = int(sys.argv[2])
    t = float(sys.argv[3])

    np.random.seed(42)
    t_vals = np.linspace(0, 2*np.pi, N)
    signal = np.sin(t_vals) + np.random.normal(0, 0.1, N)
    signal[::10] += np.random.normal(0, 2, N//10)  # Add outliers

    workspace = GSLFilterImpulseWorkspace(K)
    filtered, outliers = workspace.apply_filter(signal, t)

    for i in range(N):
        print(f"Data Point {i}: Value={signal[i]:.2f}, Filtered={filtered[i]:.2f}, Outlier={outliers[i]}")

