def triangular_operation(matrix):
    size = len(matrix)
    data = np.zeros((size, size), dtype=np.ctypeslib.c_float)
    for i in range(size):
        for j in range(size):
            data[i, j] = matrix[i][j]
    gsl_matrix = GSLMatrix(data.tolist())
    gsl.gsl_linalg_tri_LTL(gsl_matrix.data)
    result = np.zeros((size, size), dtype=np.ctypeslib.c_float)
    for i in range(size):
        for j in range(size):
            result[i, j] = gsl_matrix.data[i * size + j]
    return result.tolist()

