        self.size = self.data.shape[0]
        self.matrix = self.data.ctypes.data_as(ctypes.POINTER(ctypes.POINTER(ctypes.c_double)))

    def is_positive_definite(self):
        """Check if the matrix is positive definite."""
        lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        lib.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.POINTER(ctypes.c_double)), ctypes.c_int]
