        status = lib.gsl_linalg_cholesky_decomp(self.matrix, self.size)
        return status == 0

    def cholesky_decomp(self):
        """Perform Cholesky decomposition and return the lower triangular matrix."""
        lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        lib.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.POINTER(ctypes.c_double)), ctypes.c_int]
